import java.util.Scanner;

public class HospitalBilling {
    private String patientName;
    private String wardType;
    private int days;
    private double bill;

    public HospitalBilling() {
        patientName = "";
        wardType = "GENERAL";
        days = 0;
        bill = 0.0;
    }

    public void input() {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter Patient Name: ");
        patientName = in.nextLine();
        System.out.print("Enter Ward Type (ICU / CABIN / GENERAL): ");
        wardType = in.nextLine().toUpperCase();
        System.out.print("Enter Days Admitted: ");
        days = in.nextInt();
    }

    public void calculate() {
        double dailyRate;
        switch (wardType) {
            case "ICU": dailyRate = 6000.0; break;
            case "CABIN": dailyRate = 3500.0; break;
            case "GENERAL": dailyRate = 1500.0; break;
            default:
                dailyRate = 1500.0;
                System.out.println("Defaulted to General ward rate.");
        }

        double roomTotal = days * dailyRate;
        if (days > 10) roomTotal -= (0.05 * roomTotal);
        bill = roomTotal + 1000.0; // Consultation fee
    }

    public void display() {
        System.out.println("\n============== HOSPITAL INVOICE ==============");
        System.out.println("Patient Name : " + patientName);
        System.out.println("Ward Type    : " + wardType);
        System.out.println("Days Stayed  : " + days);
        System.out.println("Total Bill   : Rs. " + bill);
        System.out.println("==============================================");
    }

    public static void main(String[] args) {
        HospitalBilling hb = new HospitalBilling();
        hb.input();
        hb.calculate();
        hb.display();
    }
}
```

