import java.util.Scanner;

public class MajorityElementFinder {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        final int N = 10;
        int[] arr = new int[N];

        System.out.println("Enter " + N + " integers:");
        for (int i = 0; i < N; i++) arr[i] = sc.nextInt();

        int majority = -1;
        boolean found = false;

        for (int i = 0; i < N; i++) {
            int count = 0;
            for (int j = 0; j < N; j++) {
                if (arr[j] == arr[i]) count++;
            }
            if (count > N / 2) {
                majority = arr[i];
                found = true;
                break;
            }
        }

        if (found) {
            System.out.println("\nMajority Element = " + majority + " (appears > " + (N / 2) + " times).");
        } else {
            System.out.println("\nNo Majority Element exists in the array.");
        }
    }
}
```

