import java.util.Scanner;

public class SmithNumberCheck {
    public static int sumOfDigits(int n) {
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter positive integer: ");
        int num = sc.nextInt();

        int temp = num;
        int factorDigitSum = 0;
        int factorCount = 0;

        for (int d = 2; d * d <= temp; d++) {
            while (temp % d == 0) {
                factorDigitSum += sumOfDigits(d);
                factorCount++;
                temp /= d;
            }
        }
        if (temp > 1) {
            factorDigitSum += sumOfDigits(temp);
            factorCount++;
        }

        // Composite check: must have > 1 prime factors
        if (factorCount <= 1) {
            System.out.println(num + " is prime or <= 1. It CANNOT be a Smith Number.");
            return;
        }

        int numberDigitSum = sumOfDigits(num);
        System.out.println("Number Digit Sum         = " + numberDigitSum);
        System.out.println("Prime Factors Digit Sum  = " + factorDigitSum);

        if (numberDigitSum == factorDigitSum) {
            System.out.println(num + " is a SMITH NUMBER.");
        } else {
            System.out.println(num + " is NOT a Smith Number.");
        }
    }
}
```

