import java.util.Scanner;

public class OrthogonalMatrixCheck {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        final int N = 3;
        int[][] A = new int[N][N];
        int[][] AT = new int[N][N];
        int[][] prod = new int[N][N];

        System.out.println("Enter elements for 3x3 matrix:");
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                A[i][j] = in.nextInt();
                AT[j][i] = A[i][j]; // Transpose
            }
        }

        // Multiply A and AT
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                for (int k = 0; k < N; k++) {
                    prod[i][j] += A[i][k] * AT[k][j];
                }
            }
        }

        boolean isOrthogonal = true;
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (i == j && prod[i][j] != 1) isOrthogonal = false;
                if (i != j && prod[i][j] != 0) isOrthogonal = false;
            }
        }

        System.out.println("\nProduct Matrix (A * A^T):");
        for (int[] row : prod) {
            for (int v : row) System.out.printf("%4d", v);
            System.out.println();
        }

        if (isOrthogonal) {
            System.out.println("The matrix is ORTHOGONAL.");
        } else {
            System.out.println("The matrix is NOT Orthogonal.");
        }
    }
}
```

