public class OverloadSort {
    public void sort(int[] arr) {
        for (int i = 0; i < arr.length - 1; i++) {
            for (int j = 0; j < arr.length - 1 - i; j++) {
                if (arr[j] > arr[j + 1]) {
                    int t = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = t;
                }
            }
        }
    }

    public void sort(char[] arr) {
        for (int i = 0; i < arr.length - 1; i++) {
            for (int j = 0; j < arr.length - 1 - i; j++) {
                if (arr[j] > arr[j + 1]) {
                    char t = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = t;
                }
            }
        }
    }

    public static void main(String[] args) {
        OverloadSort s = new OverloadSort();

        int[] nums = {54, 12, 89, 23, 7};
        s.sort(nums);
        System.out.print("Sorted Integers  : ");
        for (int v : nums) System.out.print(v + " ");
        System.out.println();

        char[] chars = {'E', 'A', 'D', 'B', 'C'};
        s.sort(chars);
        System.out.print("Sorted Characters: ");
        for (char c : chars) System.out.print(c + " ");
        System.out.println();
    }
}
```

